import { test } from 'node:test';
import assert from 'node:assert/strict';
import { greet } from './greet.ts';
test('edge', () => {
  assert.equal(greet(undefined, 'es'), '¡Hola, world!');
  assert.equal(greet('', 'es'), '¡Hola, !');
  assert.equal(greet('Shurik', ''), 'Hello, Shurik!');
  assert.equal(greet('Shurik', 'constructor'), 'Hello, Shurik!');
  assert.equal(greet('Shurik', '__proto__'), 'Hello, Shurik!');
  assert.equal(greet('Shurik', undefined as any), 'Hello, Shurik!');
});
EOF
